const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const card=(title,body,meta='')=>`<section class="card"><h2>${title}${meta?`<small>${meta}</small>`:''}</h2>${body}</section>`;
const input=(id,label,value='',type='text',extra='')=>`<label>${label}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(id,label,values)=>`<label>${label}<select id="${id}">${values.map(x=>`<option value="${esc(Array.isArray(x)?x[0]:x)}">${esc(Array.isArray(x)?x[1]:x)}</option>`).join('')}</select></label>`;
const area=(id,label,value='')=>`<label>${label}<textarea id="${id}" spellcheck="false">${esc(value)}</textarea></label>`;
const btn=(id,text,primary=false)=>`<button id="${id}" class="${primary?'primary':''}">${text}</button>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const stats=items=>`<div class="result-grid">${items.map(([label,value,cls=''])=>`<div class="stat ${cls}"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div>`;
const hint=(s,w=false)=>`<div class="hint ${w?'warning':''}">${s}</div>`;
const out=(id='output')=>`<div id="${id}" aria-live="polite"></div>`;
const action=(id,fn)=>$(id).onclick=()=>safe(fn);
const safe=fn=>{try{const r=fn();if(r&&r.catch)r.catch(showError);return r;}catch(e){showError(e);}};
function showError(e){const d=$('output')||$('surface');let p=d.querySelector('.error');if(!p){p=document.createElement('div');p.className='error';d.prepend(p);}p.textContent=e.message||String(e);}
function toast(text){$('toast').textContent=text;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',2500);}
async function copy(text){await navigator.clipboard.writeText(text);toast('Copied to clipboard');}
function download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
let current='ipv4',cleanup=()=>{};
const PAGES=GROUPS.flatMap(([group,items])=>items.map(([id,title,icon])=>({id,title,icon,group})));
function nav(query=''){$('nav').innerHTML=GROUPS.map(([name,items])=>{const filtered=items.filter(x=>x[1].toLowerCase().includes(query.toLowerCase()));return filtered.length?`<details open><summary>${name}</summary>${filtered.map(([id,title,icon])=>`<button data-page="${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}><span>${icon}</span><span>${title}</span></button>`).join('')}</details>`:'';}).join('');$('nav').querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));}
function navigate(id,update=true){const page=PAGES.find(x=>x.id===id)||PAGES.find(x=>x.id==='ipv4');cleanup();cleanup=()=>{};current=page.id;if(update)history.replaceState(null,'','#'+current);$('category').textContent=page.group;$('title').textContent=page.title;$('subtitle').textContent=DESCRIPTIONS[current]||'Explore the controls, follow the result, and practice the underlying concepts.';$('breadcrumb').innerHTML=esc(page.group)+' <span>/ '+esc(page.title)+'</span>';$('level').textContent=['Learn','Calculator'].includes(page.group)?'ADDRESSING LAB':page.group.includes('Simulator')?'SIMULATION':'LEARNING WORKSPACE';nav($('search').value);$('sidebar').classList.remove('open');$('surface').innerHTML='';safe(()=>render(current));window.scrollTo(0,0);}
function render(id){if(id==='ipv4')return ipv4();if(typeof renderModule==='function')return renderModule(id);}
function bitMap(n,p){const bits=Net.binary(n).replace(/\./g,'');return `<div class="octets">${Net.str(n).split('.').map((v,i)=>`<div><div class="octet-title mono">${v}<span>OCTET ${i+1}</span></div><div class="bits">${bits.slice(i*8,i*8+8).split('').map((b,j)=>`<span class="bit ${i*8+j>=p?'host':''}">${b}</span>`).join('')}</div></div>`).join('')}</div><div class="legend"><span><b>■</b> ${p} network bits</span><span><em>■</em> ${32-p} host bits</span></div>`;}
function ipv4(){const q=new URLSearchParams(location.search);$('surface').innerHTML=`<div class="grid"><div>${card('Network input',`<div class="fields">${input('ip','IPv4 address',q.get('ip')||'192.168.10.0')}${input('pfx','Prefix',q.get('pfx')||'/26')}</div><div class="actions">${btn('calculate','Calculate subnet',true)}${btn('share','Copy link')}${btn('print','Print / save PDF')}</div><div class="chips">${['192.168.10.0/26','10.0.0.0/8','172.16.5.70/20','10.10.10.0/30'].map(x=>`<button data-example="${x}">${x}</button>`).join('')}</div>`)}${card('32-bit address map',out('bits'),'NETWORK / HOST')}${card('How the calculation works',out('steps'))}</div><div>${card('Subnet results',out(),'LIVE RESULTS')}${card('Address membership',`<div class="fields">${input('check-ip','IP to check','192.168.10.33')}</div>${btn('check','Check address')}${out('membership')}`)}${hint('A /31 uses both addresses on a point-to-point link. A /32 identifies one host. Neither has a conventional broadcast address.')}</div></div>`;
 const calc=()=>{const n=Net.subnet($('ip').value,$('pfx').value);$('output').innerHTML=stats([['Network address',n.network,'highlight'],['Broadcast',n.broadcast],['First usable host',n.first],['Last usable host',n.last],['Usable hosts',n.hosts.toLocaleString(),'big highlight'],['Total addresses',n.size.toLocaleString(),'big'],['Subnet mask',n.mask],['Wildcard mask',n.wildcard],['CIDR',n.cidr,'full'],['Address category',Net.classify(n.ip).type,'full']]);$('bits').innerHTML=bitMap(Net.ip(n.ip),n.p);$('steps').innerHTML=[['Separate the address',`${n.p} network bits identify the subnet; ${32-n.p} host bits select addresses inside it.`],['Build the mask',`Set the first ${n.p} bits to 1. The dotted-decimal mask is ${n.mask}.`],['Find the network',`The bitwise AND of ${n.ip} and ${n.mask} is ${n.network}.`],['Find the upper boundary',`The block contains ${n.size.toLocaleString()} addresses, ending at ${n.lastAddress}.`],['Count usable addresses',n.p<31?`Reserve the network and broadcast: ${n.size.toLocaleString()} − 2 = ${n.hosts.toLocaleString()}.`:`All ${n.size} addresses are usable for this ${n.p===31?'point-to-point subnet':'host route'}.`]].map(([h,p],i)=>`<div class="step"><span>${i+1}</span><div><strong>${h}</strong><p>${p}</p></div></div>`).join('');return n;};action('calculate',calc);for(const id of ['ip','pfx'])$(id).onchange=()=>safe(calc);$('surface').querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{const [s,p]=b.dataset.example.split('/');$('ip').value=s;$('pfx').value='/'+p;safe(calc);});action('check',()=>{const n=calc(),v=Net.ip($('check-ip').value),within=v>=n.start&&v<=n.end;let kind=within?'Usable host':'Outside this subnet';if(within&&n.p<31&&(v===n.start||v===n.end))kind=v===n.start?'Network address':'Broadcast address';$('membership').innerHTML=hint(esc($('check-ip').value)+' — '+kind);});action('share',()=>{const n=calc(),url=new URL(location.href);url.searchParams.set('ip',n.ip);url.searchParams.set('pfx','/'+n.p);return copy(url.href);});action('print',()=>window.print());calc();}
$('search').oninput=e=>nav(e.target.value);$('menu').onclick=()=>$('sidebar').classList.toggle('open');$('theme').onclick=()=>{document.body.classList.toggle('light');try{localStorage.setItem('param-lab-theme',document.body.classList.contains('light')?'light':'dark');}catch{}};$('fullscreen').onclick=()=>safe(()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen());try{if(localStorage.getItem('param-lab-theme')==='light')document.body.classList.add('light');}catch{}window.onhashchange=()=>navigate(location.hash.slice(1),false);navigate(location.hash.slice(1)||'ipv4',false);
